use std::borrow::Cow;

fn normalize(input: &str) -> Cow<'_, str> {
    if input.contains('\t') {
        Cow::Owned(input.replace('\t', " "))   // the clone happens here
    } else {
        Cow::Borrowed(input)                    // no allocation at all
    }
}

